Here's a custom React hook for synchronizing state with localStorage:

```jsx
import { useState, useEffect } from 'react';

function useLocalStorage(key, initialValue) {
    // Get stored value or use initial
    const [storedValue, setStoredValue] = useState(() => {
        try {
            const item = window.localStorage.getItem(key);
            return item ? JSON.parse(item) : initialValue;
        } catch (error) {
            console.error('Error reading localStorage:', error);
            return initialValue;
        }
    });

    // Update localStorage when state changes
    useEffect(() => {
        try {
            window.localStorage.setItem(key, JSON.stringify(storedValue));
        } catch (error) {
            console.error('Error writing to localStorage:', error);
        }
    }, [key, storedValue]);

    // Sync across tabs
    useEffect(() => {
        function handleStorageChange(e) {
            if (e.key === key) {
                try {
                    setStoredValue(JSON.parse(e.newValue));
                } catch {}
            }
        }
        window.addEventListener('storage', handleStorageChange);
        return () => window.removeEventListener('storage', handleStorageChange);
    }, [key]);

    return [storedValue, setStoredValue];
}

// Usage
export default function App() {
    const [theme, setTheme] = useLocalStorage('theme', 'light');
    const [user, setUser] = useLocalStorage('user', null);

    return (
        <div className={theme}>
            <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>
                Toggle Theme
            </button>
        </div>
    );
}
```

This hook handles JSON serialization/deserialization, error handling for localStorage quota exceeded or private browsing mode, and cross-tab synchronization via the storage event listener. It works as a drop-in replacement for useState with automatic persistence.
